TRANSLATIONS["pa"].update(PUNJABI_EXTRA)
for code in CODES:
    source = STRINGS.get("en", {})
    target = STRINGS.get(code, {})
    for key, english in source.items():
        translated = target.get(key)
        if isinstance(english, str) and translated and translated != english:
            TRANSLATIONS[code].setdefault(english, translated)

# Longer phrases must be replaced first to avoid translating a short fragment inside a longer phrase.
SORTED_TRANSLATIONS = {
    code: sorted(mapping.items(), key=lambda item: len(item[0]), reverse=True)
    for code, mapping in TRANSLATIONS.items()
}


def get_language_code() -> str:
    try:
        import streamlit as st
        from .i18n import LANGUAGES
        label = st.session_state.get("ui_language_label", "English")
        return LANGUAGES.get(label, "en")
    except Exception:
        return "en"


def translate_text(value: Any, lang: str | None = None, *, fragments: bool = True) -> Any:
    """Translate app copy. Preserve non-strings, URLs, code blocks and unknown source text."""
    if not isinstance(value, str):
        return value
    lang = lang or get_language_code()
    if lang == "en" or lang not in TRANSLATIONS or not value:
        return value
    if value in TRANSLATIONS[lang]:
        return TRANSLATIONS[lang][value]
    # Don't alter URLs/code or generated long answer text.
    if value.startswith(("http://", "https://", "tel:", "`", "```")):
        return value
    if not fragments:
        return value
    result = value
    for english, translated in SORTED_TRANSLATIONS[lang]:
        if english and english in result:
            result = result.replace(english, translated)
    return result


def install_streamlit_localization(st) -> None:
    """Wrap selected Streamlit display/widget functions; internal values stay unchanged."""
    if getattr(st, "_sudhaar_ui_localization_installed", False):
        return

    def patch_text_method(name: str, *, allow_fragments: bool = True):
        original = getattr(st, name, None)
        if not callable(original):
            return
        def wrapped(*args, **kwargs):
            lang = get_language_code()
            a = list(args)
            # Most display calls have text as the first positional argument.
            if a and isinstance(a[0], str):
                text_value = a[0]
                unsafe_html = bool(kwargs.get("unsafe_allow_html", False))
                is_css = "<style" in text_value and "</style>" in text_value
                is_user = "user-bubble-v6" in text_value
                is_ai_response = len(text_value) > 850 and not unsafe_html
                is_source_card = 'class="kb-card' in text_value
                if not is_css and not is_user and not is_ai_response and not is_source_card:
                    a[0] = translate_text(text_value, lang, fragments=allow_fragments)
            # Translate common descriptive keyword arguments for widgets and notices.
            for arg_name in ("label", "placeholder", "help", "caption", "title"):
                if isinstance(kwargs.get(arg_name), str):
                    kwargs[arg_name] = translate_text(kwargs[arg_name], lang)
            # Options keep their underlying English values; only their visible labels are translated.
            if name in {"selectbox", "radio", "multiselect", "select_slider"} and (len(a) >= 2 or "options" in kwargs):
                old_fmt = kwargs.get("format_func")
                kwargs["format_func"] = lambda option, old_fmt=old_fmt, lang=lang: translate_text(old_fmt(option) if old_fmt else str(option), lang)
            return original(*a, **kwargs)
        setattr(st, name, wrapped)

    # Text/HTML renderers: only known static phrases are substituted; long generated answers and user bubbles are preserved.
    for method in ("markdown", "write", "title", "header", "subheader", "caption", "text", "info", "warning", "error", "success", "exception", "toast", "spinner", "expander", "button", "link_button", "form_submit_button", "text_input", "text_area", "file_uploader", "audio_input", "chat_input", "selectbox", "radio", "multiselect", "select_slider"):
        patch_text_method(method)

    # st.tabs accepts its labels as its first argument, unlike most methods.
    original_tabs = getattr(st, "tabs", None)
    if callable(original_tabs):
        def tabs_wrapped(labels, *args, **kwargs):
            lang = get_language_code()
            translated = [translate_text(label, lang) for label in labels]
            return original_tabs(translated, *args, **kwargs)
        st.tabs = tabs_wrapped

    st._sudhaar_ui_localization_installed = True
